(()=>{var l=()=>{let e=document.querySelector(".com-unordered"),o=document.querySelector("#right-arrow"),r=document.querySelector("#left-arrow");e.scrollLeft+e.offsetWidth<e.scrollWidth&&o.classList.remove("none"),document.querySelector("#right-arrow").addEventListener("click",()=>{let t=e.scrollLeft+150;e.scroll({left:t,behavior:"smooth"}),e.scrollLeft+e.offsetWidth>=e.scrollWidth&&o.classList.add("none"),r.classList.remove("none")}),document.querySelector("#left-arrow").addEventListener("click",()=>{let t=e.scrollLeft-150;e.scroll({left:t,behavior:"smooth"}),e.scrollLeft===0&&r.classList.add("none"),o.classList.remove("none")})};l();})();
